import type { DesignContent } from "@/lib/design-content";

export const content: DesignContent = {"slug": "edit-product", "title": "UniShare · Edit product", "css": "\n:root{--ink:#14201e;--muted:#5b6866;--teal:#0b5b57;--teal-soft:#e3efed;--line:#14201e;--hair:#dfe4e3;--panel:#f4f6f5;--err:#a02a22;--white:#fff}\n*{box-sizing:border-box;margin:0;padding:0}\nbody{font-family:\"Schibsted Grotesk\",system-ui,-apple-system,\"Segoe UI\",sans-serif;color:var(--ink);background:var(--white);font-size:14px;line-height:1.45}\na{color:inherit;text-decoration:none}\nbutton,input,select,textarea{font:inherit;color:inherit}\nbutton{cursor:pointer}\n:focus-visible{outline:2px solid var(--teal);outline-offset:2px}\n.nav{border-bottom:2px solid var(--line);height:56px;display:flex;align-items:center;justify-content:space-between;padding:0 48px;gap:24px}\n.brand{display:flex;align-items:center;gap:10px;font-weight:700;font-size:20px}\n.brand svg{width:24px;height:24px;color:var(--teal)}\n.nav ul{list-style:none;display:flex;gap:22px;font-size:13px}\n.nav ul a{padding:19px 0;display:block;border-bottom:2px solid transparent;margin-bottom:-2px}\n.nav ul a.on{color:var(--teal);font-weight:600;border-color:var(--teal)}\n.nav-r{display:flex;align-items:center;gap:18px;font-size:13px}\n.nav-r svg.i{width:15px;height:15px}\n.bell{display:flex;align-items:flex-start;gap:2px;color:var(--teal)}\n.bell sup{font-size:8px;font-weight:600;margin-top:2px}\n.sos{display:flex;align-items:center;gap:5px;font-weight:600;color:var(--teal)}\n.user{display:flex;align-items:center;gap:8px}\n.avatar{width:28px;height:28px;border-radius:50%;background:var(--teal-soft);border:1px solid var(--teal);color:var(--teal);font-size:10px;display:grid;place-items:center;font-weight:600}\n.user b{font-weight:600;font-size:12px;line-height:1.2;display:block}\n.user small{display:block;color:var(--muted);font-size:10px;line-height:1.2}\nmain{max-width:644px;margin:0 auto;padding:0 0 40px}\n.crumbs{font-size:11px;color:var(--muted);margin:19px 0 24px;display:flex;gap:6px}\n.head{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;margin-bottom:22px}\n.eyebrow{font-size:9.5px;letter-spacing:.04em;color:var(--teal);font-weight:600;text-transform:uppercase;margin-bottom:10px}\nh1{font-size:30px;line-height:1.1;font-weight:800;letter-spacing:-.01em;margin-bottom:10px}\n.lede{color:var(--muted);font-size:13px}\n.pill{background:var(--teal-soft);color:var(--teal);font-size:9px;font-weight:700;border-radius:999px;padding:4px 10px;white-space:nowrap;margin-top:40px}\n.head .btn.live{margin-top:14px;padding:10px 14px}\n.banner{background:var(--teal-soft);border-radius:8px;padding:15px 18px;display:flex;gap:12px;margin-bottom:22px}\n.banner svg{width:15px;height:15px;color:var(--teal);flex:none;margin-top:2px}\n.banner b{display:block;color:var(--teal);font-size:11px;margin-bottom:2px}\n.banner span{font-size:9.5px;color:var(--muted)}\n.hist .line{font-size:9.5px;color:var(--muted);margin-bottom:6px}\n.hist .pill2{display:inline-block;background:var(--teal-soft);color:var(--teal);font-size:8.5px;font-weight:700;border-radius:999px;padding:3px 9px;margin:8px 0 12px}\n.hist p{font-size:9px;color:var(--muted);line-height:1.5}\n.layout{display:grid;grid-template-columns:1fr 175px;gap:16px;align-items:start}\n.col{display:flex;flex-direction:column;gap:16px;min-width:0}\n.card{border:1.5px solid var(--line);border-radius:12px;padding:20px 14px 18px}\n.card h2{font-size:17px;font-weight:700;margin-bottom:14px;line-height:1.25}\n.intro{font-size:10px;color:var(--muted);margin-bottom:18px}\n.f{margin-bottom:16px}\n.f:last-child{margin-bottom:0}\nlabel.l,.l{display:block;font-size:10.5px;font-weight:700;margin-bottom:8px}\n.in{width:100%;border:1px solid var(--hair);border-radius:8px;padding:11px 12px;font-size:11px;background:#fff;outline:0}\n.in:focus{border-color:var(--teal);outline:2px solid var(--teal);outline-offset:1px}\n.in.bad{border-color:var(--err)}\ntextarea.in{min-height:66px;resize:vertical;line-height:1.55}\n.sw{position:relative}\n.sw select{appearance:none;-webkit-appearance:none;cursor:pointer;padding-right:30px}\n.sw svg{position:absolute;right:12px;top:50%;transform:translateY(-50%);width:12px;height:12px;pointer-events:none}\n.help{font-size:9px;color:var(--muted);margin-top:8px}\n.err{display:none;font-size:9.5px;color:var(--err);margin-top:6px}\n.f.bad .err{display:block}\n.cond{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}\n.cond label{display:flex;align-items:center;justify-content:center;gap:7px;border:1px solid var(--hair);border-radius:6px;padding:10px 8px;font-size:11px;cursor:pointer;background:#fff}\n.cond input{position:absolute;opacity:0;pointer-events:none}\n.cond .dot{width:11px;height:11px;border-radius:50%;border:1.3px solid var(--ink);flex:none;display:grid;place-items:center}\n.cond input:checked+label .dot,.cond label.on .dot{border-color:var(--teal);background:var(--teal)}\n.cond label.on{background:var(--teal-soft);border:1.5px solid var(--teal);font-weight:500}\n.cond label.on .dot::after{content:\"\";width:5px;height:3px;border-left:1.5px solid #fff;border-bottom:1.5px solid #fff;transform:rotate(-45deg) translate(0,-1px)}\n.cond input:focus-visible+label{outline:2px solid var(--teal);outline-offset:2px}\n.gallery{display:grid;grid-template-columns:1fr 1fr;gap:6px 6px;margin-bottom:14px}\n.gimg img{width:100%;height:90px;object-fit:cover;border-radius:4px;display:block;background:var(--panel)}\n.gfoot{display:flex;justify-content:space-between;align-items:center;margin-top:6px;min-height:18px}\n.tag{background:var(--teal-soft);color:var(--teal);font-size:8.5px;font-weight:700;border-radius:999px;padding:3px 9px}\n.mk{background:none;border:0;font-size:8.5px;font-weight:700;color:var(--teal);padding:3px 0}\n.mk:hover{text-decoration:underline}\n.del{background:none;border:0;color:var(--teal);width:20px;height:20px;display:grid;place-items:center}\n.del svg{width:12px;height:12px}\n.drop{border:1.5px dashed var(--teal);border-radius:8px;background:var(--panel);padding:18px 12px 16px;text-align:center;margin-bottom:12px}\n.drop.over{background:var(--teal-soft)}\n.drop .big{width:18px;height:18px;color:var(--teal);margin:0 auto 10px;display:block}\n.btn{border:1.5px solid var(--teal);color:var(--teal);background:#fff;border-radius:8px;padding:8px 12px;font-weight:600;font-size:10.5px;white-space:nowrap;display:inline-flex;align-items:center;justify-content:center;gap:7px}\n.btn:hover{background:var(--teal-soft)}\n.btn svg{width:11px;height:11px}\n.btn.solid{background:var(--teal);color:#fff}\n.btn.solid:hover:not(:disabled){background:#094a47}\n.btn:disabled{opacity:.45;cursor:default}\n.drop small{display:block;font-size:8.5px;color:var(--muted);margin-top:12px}\n.two{display:grid;grid-template-columns:1fr 1fr;gap:16px}\n.note{background:var(--teal-soft);border-radius:8px;padding:12px 14px;display:flex;gap:10px;margin-top:16px}\n.note svg{width:14px;height:14px;color:var(--teal);flex:none;margin-top:1px}\n.note b{display:block;color:var(--teal);font-size:10.5px;margin-bottom:2px}\n.note span{font-size:9.5px;color:var(--muted);line-height:1.5}\n.cal{display:flex;justify-content:space-between;align-items:center;gap:12px;font-size:9.5px;color:var(--muted);margin-top:12px}\n.consent{display:flex;gap:8px;align-items:flex-start;font-size:9.5px;color:#3a4745;line-height:1.5;margin:18px 0 14px;cursor:pointer}\n.consent input{width:13px;height:13px;accent-color:var(--teal);margin-top:2px;flex:none}\n.actions{display:flex;justify-content:space-between;gap:8px}\n.actions .r{display:flex;gap:8px}\n.actions .btn{padding:10px 14px;font-size:10.5px}\n.status{font-size:10px;color:var(--teal);font-weight:600;margin-top:10px;min-height:14px}\n/* side */\n.pv img{width:100%;height:76px;object-fit:cover;border-radius:6px;display:block;margin-bottom:12px;background:var(--panel)}\n.pv .pill2{display:inline-block;background:var(--teal-soft);color:var(--teal);font-size:8.5px;font-weight:700;border-radius:999px;padding:3px 9px;margin-bottom:10px}\n.pv small{display:block;font-size:8.5px;color:var(--muted)}\n.pv h3{font-size:14px;font-weight:700;line-height:1.3;margin:10px 0 12px}\n.pv .rate{font-size:14px;font-weight:700;color:var(--teal);margin-bottom:10px}\n.pv .dep,.pv .pick{font-size:8.5px;color:var(--muted);margin-bottom:10px}\n.pv .own{display:flex;gap:6px;align-items:flex-start;font-size:9px}\n.pv .own svg{width:12px;height:12px;color:var(--teal);flex:none;margin-top:1px}\n.pv .own b{display:block;font-weight:700;line-height:1.3}\n.pv .own span{font-size:8.5px;color:var(--muted)}\n.tips h2{font-size:15px}\n.tip{display:flex;gap:8px;margin-bottom:12px;font-size:9px}\n.tip:last-child{margin-bottom:0}\n.tip svg{width:12px;height:12px;color:var(--teal);flex:none;margin-top:1px}\n.tip b{display:block;font-size:9px;margin-bottom:2px}\n.tip span{display:block;font-size:8.5px;color:var(--muted);line-height:1.5}\nfooter{border-top:2px solid var(--line);padding:22px 48px 26px;display:flex;justify-content:space-between;font-size:11.5px;color:var(--muted)}\nfooter nav{display:flex;gap:22px}\nfooter nav a{color:var(--teal);font-weight:600}\n@media (max-width:1040px){.nav ul{display:none}}\n@media (max-width:820px){main{max-width:560px}.layout{grid-template-columns:1fr}.pv img{height:140px}}\n@media (max-width:640px){\n  main{padding:0 20px 40px}\n  .nav,footer{padding-left:20px;padding-right:20px}\n  .two{grid-template-columns:1fr}\n  .cond{grid-template-columns:1fr}\n  .head{flex-direction:column;gap:0}.pill{margin-top:12px}\n  .actions{flex-direction:column}.actions .r{flex-direction:column}\n  footer{flex-direction:column;gap:10px}\n}\n", "body": "\n<header class=\"nav\">\n  <a class=\"brand\" href=\"/\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\"><circle cx=\"7\" cy=\"12\" r=\"4\"/><circle cx=\"17\" cy=\"12\" r=\"4\"/></svg>UniShare</a>\n  <ul>\n    <li><a href=\"/campus-home\">Home</a></li><li><a href=\"/marketplace\">Marketplace</a></li><li><a class=\"on\" href=\"/my-products\">My products</a></li><li><a href=\"/my-rentals\">My rentals</a></li><li><a href=\"/ride-home-and-search\">Rides</a></li><li><a href=\"/wallet-overview\">Wallet</a></li><li><a href=\"/favorites\">Favorites</a></li>\n  </ul>\n  <div class=\"nav-r\">\n    <span class=\"bell\" aria-label=\"3 notifications\"><svg class=\"i\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M6 17V11a6 6 0 0 1 12 0v6l1.5 2h-15zM10 21h4\"/></svg><sup>3</sup></span>\n    <a class=\"sos\" href=\"/student-sos-assistance\"><svg class=\"i\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"><path d=\"M12 3l8 3v6c0 5-3.5 8-8 9-4.5-1-8-4-8-9V6z\"/><path d=\"M9 12l2 2 4-4\" stroke-linecap=\"round\"/></svg>SOS</a>\n    <div class=\"user\"><span class=\"avatar\">FR</span><div><b>Farhana Rahman</b><small>My profile</small></div></div>\n  </div>\n</header>\n\n<main>\n  <nav class=\"crumbs\" aria-label=\"Breadcrumb\"><a href=\"/campus-home\">Home</a><span>›</span><a href=\"/my-products\">My products</a><span>›</span><span>Edit product</span></nav>\n  <div class=\"head\">\n    <div>\n      <div class=\"eyebrow\">University of Dhaka · Verified students only</div>\n      <h1>Edit product</h1>\n      <p class=\"lede\">Keep your Canon EOS 200D listing accurate and ready to share.</p>\n    </div>\n    <a class=\"btn live\" href=\"/product-details\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 4h6v6M20 4l-9 9M18 14v5a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V7a1 1 0 0 1 1-1h5\"/></svg>View live listing</a>\n  </div>\n\n  <div class=\"banner\" role=\"note\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 3l8 3v6c0 5-3.5 8-8 9-4.5-1-8-4-8-9V6z\"/><path d=\"M9 12l2 2 4-4\"/></svg><div><b>You’re editing your own listing.</b><span>Farhana Rahman · University of Dhaka. Updates apply to new requests only; confirmed rentals keep their existing terms.</span></div></div>\n\n  <form id=\"form\" novalidate onsubmit=\"return false\">\n  <div class=\"layout\">\n    <div class=\"col\">\n      <section class=\"card\">\n        <h2>Product details</h2>\n        <p class=\"intro\">Tell fellow students exactly what they’re borrowing. All fields marked * are required.</p>\n        <div class=\"f\" id=\"fTitle\">\n          <label class=\"l\" for=\"title\">Product title *</label>\n          <input class=\"in\" id=\"title\" maxlength=\"80\" value=\"Canon EOS 200D\">\n          <div class=\"help\"><span id=\"tc\">14</span> / 80 characters</div>\n          <div class=\"err\">Add a title so students know what you’re lending.</div>\n        </div>\n        <div class=\"f\" id=\"fDesc\">\n          <label class=\"l\" for=\"desc\">Description *</label>\n          <textarea class=\"in\" id=\"desc\">Canon EOS 200D with 18–55mm kit lens, battery, charger and camera strap. Great for campus events and photography assignments. Minor marks on the body; lens and screen are clean. Please keep it dry and return all accessories.</textarea>\n          <div class=\"err\">Describe the item, what’s included and how it should be returned.</div>\n        </div>\n        <div class=\"f\">\n          <label class=\"l\" for=\"cat\">Category *</label>\n          <div class=\"sw\"><select class=\"in\" id=\"cat\"><option>Cameras</option><option>Travel essentials</option><option>Camera accessories</option><option>Study essentials</option><option>Calculators</option><option>Laptop chargers</option><option>Phone chargers</option><option>AirPods</option><option>Footballs</option><option>Earphones</option></select>\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M6 9l6 6 6-6\"/></svg></div>\n        </div>\n        <div class=\"f\">\n          <div class=\"l\" id=\"condL\">Product condition *</div>\n          <div class=\"cond\" role=\"radiogroup\" aria-labelledby=\"condL\" id=\"cond\">\n            <input type=\"radio\" name=\"cond\" id=\"c1\" value=\"Like new\"><label for=\"c1\"><span class=\"dot\"></span>Like new</label>\n            <input type=\"radio\" name=\"cond\" id=\"c2\" value=\"Good\" checked><label for=\"c2\" class=\"on\"><span class=\"dot\"></span>Good</label>\n            <input type=\"radio\" name=\"cond\" id=\"c3\" value=\"Fair\"><label for=\"c3\"><span class=\"dot\"></span>Fair</label>\n          </div>\n          <div class=\"help\" id=\"condHelp\">Good: fully working, with light signs of use. Describe any marks or missing parts.</div>\n        </div>\n      </section>\n\n      <section class=\"card\">\n        <h2>Images *</h2>\n        <p class=\"intro\">Show the actual item and any wear. First image is the cover. Add up to 5 photos.</p>\n        <div class=\"gallery\" id=\"gallery\"></div>\n        <div class=\"drop\" id=\"drop\">\n          <svg class=\"big\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"4\" width=\"15\" height=\"15\" rx=\"2\"/><circle cx=\"8\" cy=\"9\" r=\"1.5\"/><path d=\"M3 16l4-4 4 4 3-3 4 4M19 3v5M16.500 5.500h5\"/></svg>\n          <button class=\"btn\" type=\"button\" id=\"upload\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 16V5M7.500 9.500L12 5l4.500 4.500M4 19h16\"/></svg>Upload images</button>\n          <small>Drag files here · JPG or PNG · Up to 5 MB each</small>\n          <input type=\"file\" id=\"file\" accept=\"image/jpeg,image/png\" multiple hidden>\n        </div>\n        <div class=\"help\" id=\"imgHelp\">2 of 5 images added · Use the image actions to change your cover or remove a photo.</div>\n        <div class=\"f bad\" style=\"margin:8px 0 0\"><div class=\"err\" id=\"imgErr\">Add at least one photo of the actual item.</div></div>\n      </section>\n\n      <section class=\"card\">\n        <h2>Token pricing</h2>\n        <div class=\"two\">\n          <div class=\"f\" id=\"fRate\"><label class=\"l\" for=\"rate\">Price per day (tokens) *</label><input class=\"in\" id=\"rate\" type=\"number\" min=\"1\" value=\"60\"><div class=\"help\">Rental fee for each booked day</div><div class=\"err\">Enter a price of 1 token or more.</div></div>\n          <div class=\"f\" id=\"fDep\"><label class=\"l\" for=\"dep\">Security deposit (tokens) *</label><input class=\"in\" id=\"dep\" type=\"number\" min=\"0\" value=\"300\"><div class=\"help\">Refundable; held separately from the rental fee</div><div class=\"err\">Enter a deposit of 0 tokens or more.</div></div>\n        </div>\n        <div class=\"note\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 3l8 3v6c0 5-3.5 8-8 9-4.5-1-8-4-8-9V6z\"/><path d=\"M9 12l2 2 4-4\"/></svg>\n          <div><b>Rental price and deposit are different.</b><span>The rental fee is your earning. The security deposit is held in the borrower’s wallet and released after a confirmed return.</span></div></div>\n      </section>\n\n      <section class=\"card\">\n        <h2>Pickup &amp; availability</h2>\n        <div class=\"f\"><label class=\"l\" for=\"loc\">Campus pickup location *</label>\n          <div class=\"sw\"><select class=\"in\" id=\"loc\"><option>TSC, University of Dhaka</option><option>Science Library, University of Dhaka</option><option>Arts Building, University of Dhaka</option><option>Curzon Hall, University of Dhaka</option><option>Central Library, University of Dhaka</option></select><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M6 9l6 6 6-6\"/></svg></div></div>\n        <div class=\"two\">\n          <div class=\"f\"><label class=\"l\" for=\"avail\">Listing availability *</label>\n            <div class=\"sw\"><select class=\"in\" id=\"avail\"><option>Available, except blocked dates</option><option>Available from 20 October 2026</option><option>Available from 25 October 2026</option></select><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M6 9l6 6 6-6\"/></svg></div></div>\n          <div class=\"f\"><label class=\"l\" for=\"status\">Listing status</label>\n            <div class=\"sw\"><select class=\"in\" id=\"status\"><option value=\"live\">Active — accepting requests</option><option value=\"paused\">Paused — not accepting requests</option></select><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M6 9l6 6 6-6\"/></svg></div></div>\n        </div>\n        <div class=\"cal\"><span>Booked: 16–18 Oct · Unavailable: 23–25 Oct. Confirmed dates cannot be changed here.</span>\n          <button class=\"btn\" type=\"button\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><rect x=\"4\" y=\"5\" width=\"16\" height=\"15\" rx=\"2\"/><path d=\"M4 10h16M9 5V3M15 5V3\"/></svg>Manage calendar</button></div>\n      </section>\n\n      <label class=\"consent\"><input type=\"checkbox\" id=\"own\" checked><span>I own this item and confirm the photos, condition and token prices are accurate. This listing is only for verified University of Dhaka students.</span></label>\n      <div class=\"actions\">\n        <button class=\"btn\" type=\"button\" id=\"cancel\">Cancel</button>\n        <button class=\"btn solid\" type=\"button\" id=\"publish\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg>Save changes</button>\n      </div>\n      <div class=\"status\" id=\"msg\" role=\"status\"></div>\n    </div>\n\n    <aside class=\"col\">\n      <section class=\"card pv\">\n        <h2>Listing preview</h2>\n        <img id=\"pvImg\" src=\"data:image/jpeg;base64,\" alt=\"Cover preview\">\n        <span class=\"pill2\" id=\"pvState\">Active listing</span>\n        <small id=\"pvCat\">Cameras · Good condition</small>\n        <h3 id=\"pvTitle\">Canon EOS 200D</h3>\n        <div class=\"rate\" id=\"pvRate\">60 tokens / day</div>\n        <div class=\"dep\" id=\"pvDep\">300 tokens refundable deposit</div>\n        <div class=\"pick\" id=\"pvPick\">Pickup: TSC, DU</div>\n        <div class=\"own\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M8 12.5l2.800 2.800L16 9.500\"/></svg><div><b>Farhana Rahman</b><span>You · Verified DU student</span></div></div>\n      </section>\n      <section class=\"card tips\">\n        <h2>A clear listing shares better</h2>\n        <div class=\"tip\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 8h3l2-3h6l2 3h3v11H4z\"/><circle cx=\"12\" cy=\"13\" r=\"3.500\"/></svg><div><b>Use your own photos</b><span>Show every included accessory and any visible wear.</span></div></div>\n        <div class=\"tip\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M8 12.5l2.800 2.800L16 9.500\"/></svg><div><b>Keep condition honest</b><span>A working item can still have marks. Describe them clearly.</span></div></div>\n        <div class=\"tip\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><rect x=\"4\" y=\"5\" width=\"16\" height=\"15\" rx=\"2\"/><path d=\"M4 10h16M9 5V3M15 5V3\"/></svg><div><b>Keep your dates current</b><span>Block days you need the item yourself. Existing bookings stay protected.</span></div></div>\n      </section>\n      <section class=\"card hist\">\n        <h2>Listing history</h2>\n        <div class=\"line\">Created 4 October 2026</div>\n        <div class=\"line\">Last updated today, 8:00 AM</div>\n        <span class=\"pill2\">4 completed rentals</span>\n        <p>Changes to pricing apply only to new requests. Confirmed bookings keep their original price.</p>\n      </section>\n    </aside>\n  </div>\n  </form>\n</main>\n\n<footer>\n  <span>UniShare. Made for university students in Bangladesh.</span>\n  <nav><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/get-help\">Get help</a><a href=\"/\">Log out</a></nav>\n</footer>\n\n\n", "scripts": ["\n(function(){\n  var $=function(id){return document.getElementById(id)};\n  var imgs=[{src:\"data:image/jpeg;base64,\"},{src:\"data:image/jpeg;base64,\"}];\n  var MAX=5;\n  var HELP={\"Like new\":\"Like new: fully working with no visible wear. Choose the condition that best matches your item.\",\"Good\":\"Good: fully working with light signs of use. Choose the condition that best matches your item.\",\"Fair\":\"Fair: fully working with visible wear. Describe any marks in the description.\"};\n  var TRASH='<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 7h16M10 11v6M14 11v6M6 7l1 13h10l1-13M9 7V4h6v3\"/></svg>';\n  function cond(){return document.querySelector('input[name=cond]:checked').value}\n  function renderGallery(){\n    var g=$('gallery');g.innerHTML='';\n    imgs.forEach(function(im,i){\n      var d=document.createElement('div');d.className='gimg';\n      var img=document.createElement('img');img.src=im.src;img.alt='Product photo '+(i+1);\n      var f=document.createElement('div');f.className='gfoot';\n      var left=i===0?'<span class=\"tag\">Cover photo</span>':'<button type=\"button\" class=\"mk\" data-mk=\"'+i+'\">Make cover</button>';\n      f.innerHTML=left+'<button type=\"button\" class=\"del\" data-del=\"'+i+'\" aria-label=\"Remove photo '+(i+1)+'\">'+TRASH+'</button>';\n      d.appendChild(img);d.appendChild(f);g.appendChild(d);\n    });\n    $('imgHelp').textContent=imgs.length+' of '+MAX+' images added · Use the image actions to change your cover or remove a photo.';\n    $('imgErr').style.display=imgs.length?'none':'block';\n    $('upload').disabled=imgs.length>=MAX;\n    if(imgs.length)$('pvImg').src=imgs[0].src;\n  }\n  $('gallery').addEventListener('click',function(e){\n    var m=e.target.closest('[data-mk]'),d=e.target.closest('[data-del]');\n    if(m){var i=+m.dataset.mk;var x=imgs.splice(i,1)[0];imgs.unshift(x);renderGallery()}\n    if(d){imgs.splice(+d.dataset.del,1);renderGallery()}\n  });\n  function addFiles(list){\n    var msg=$('msg');msg.textContent='';\n    Array.prototype.forEach.call(list,function(f){\n      if(imgs.length>=MAX)return;\n      if(!/^image\\/(jpeg|png)$/.test(f.type)){msg.textContent='Only JPG or PNG files can be added.';return}\n      if(f.size>5*1048576){msg.textContent=f.name+' is over 5 MB.';return}\n      var r=new FileReader();r.onload=function(){if(imgs.length<MAX){imgs.push({src:r.result});renderGallery()}};r.readAsDataURL(f);\n    });\n  }\n  $('upload').addEventListener('click',function(){$('file').click()});\n  $('file').addEventListener('change',function(){addFiles(this.files);this.value=''});\n  var drop=$('drop');\n  ['dragenter','dragover'].forEach(function(t){drop.addEventListener(t,function(e){e.preventDefault();drop.classList.add('over')})});\n  ['dragleave','drop'].forEach(function(t){drop.addEventListener(t,function(e){e.preventDefault();drop.classList.remove('over')})});\n  drop.addEventListener('drop',function(e){addFiles(e.dataTransfer.files)});\n\n  function preview(){\n    $('tc').textContent=$('title').value.length;\n    $('pvTitle').textContent=$('title').value.trim()||'Untitled product';\n    $('pvCat').textContent=$('cat').value+' · '+cond()+' condition';\n    $('pvRate').textContent=($('rate').value||0)+' tokens / day';\n    $('pvDep').textContent=($('dep').value||0)+' tokens refundable deposit';\n    $('pvPick').textContent='Pickup: '+$('loc').value.replace('University of Dhaka','DU');\n    $('condHelp').textContent=HELP[cond()];\n    document.querySelectorAll('.cond label').forEach(function(l){l.classList.remove('on')});\n    document.querySelector('label[for='+document.querySelector('input[name=cond]:checked').id+']').classList.add('on');\n    var live=$('status').value==='live';\n    $('pvState').textContent=live?'Active listing':'Paused listing';\n  }\n  ['title','desc','cat','rate','dep','loc','status','avail'].forEach(function(id){$(id).addEventListener('input',preview);$(id).addEventListener('change',preview)});\n  $('cond').addEventListener('change',preview);\n\n  function validate(){\n    var ok=true;\n    function chk(id,fid,test){var good=test();$(fid).classList.toggle('bad',!good);$(id).classList.toggle('bad',!good);if(!good)ok=false}\n    chk('title','fTitle',function(){return $('title').value.trim().length>0});\n    chk('desc','fDesc',function(){return $('desc').value.trim().length>0});\n    chk('rate','fRate',function(){return +$('rate').value>=1});\n    chk('dep','fDep',function(){return $('dep').value!==''&&+$('dep').value>=0});\n    if(!imgs.length)ok=false;\n    return ok;\n  }\n  $('publish').addEventListener('click',function(){\n    if(!$('own').checked){$('msg').textContent='Confirm that you own this item before saving.';return}\n    if(!validate()){$('msg').textContent='Fix the highlighted fields to save.';return}\n    $('msg').textContent='Changes saved. New requests will use the updated price and details.';\n  });\n  $('cancel').addEventListener('click',function(){\n    if(confirm('Discard your changes?')){location.reload()}\n  });\n  renderGallery();preview();\n})();\n"], "fonts": ["https://fonts.googleapis.com/css2?family=Schibsted+Grotesk:wght@400;500;600;700;800&display=swap"]};

export default content;
